class Solution:
    def maxNiceDivisors(self, primeFactors: int) -> int:
        k = primeFactors
        dp = [0] * (k + 1)
        dp[0] = 1
        for i in range(1, k + 1):
            for j in range(1, i + 1):
                dp[i] = max(dp[i], j * dp[i - j])
        return dp[k]

