class Solution {
public:
    int maxNiceDivisors(int primeFactors) {
        int k = primeFactors;
        vector<unsigned long long> dp(k + 1);
        dp[0] = 1;
        for (int i = 1; i <= k; ++i)
            for (int j = 1; j <= i; ++j)
                dp[i] = max(dp[i], (unsigned long long)j * dp[i - j]);
        return (int)dp[k];
    }
};

