class Solution {
    private static final long MOD = 1_000_000_007L;

    private long pw(long b, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    public int maxNiceDivisors(int primeFactors) {
        if (primeFactors <= 3) return primeFactors;
        long q = primeFactors / 3, r = primeFactors % 3;
        if (r == 0) return (int) pw(3, q);
        if (r == 1) return (int) (pw(3, q - 1) * 4 % MOD);
        return (int) (pw(3, q) * 2 % MOD);
    }
}

