var maxNiceDivisors = function(primeFactors) {
    const MOD = 1000000007n;
    const pw = (b, e) => {
        let res = 1n;
        while (e > 0n) {
            if (e & 1n) res = res * b % MOD;
            b = b * b % MOD;
            e >>= 1n;
        }
        return res;
    };
    if (primeFactors <= 3) return primeFactors;
    const q = BigInt(Math.floor(primeFactors / 3)), r = primeFactors % 3;
    if (r === 0) return Number(pw(3n, q));
    if (r === 1) return Number(pw(3n, q - 1n) * 4n % MOD);
    return Number(pw(3n, q) * 2n % MOD);
};
